module watchdog_timer (  
    input clk,  
    input reset,  
    input [7:0] timeout,  
    output reg timer_reset  
);  
    reg [7:0] counter;  
    reg active;  

    always @(posedge clk) begin  
        if (reset) begin  
            counter <= 0;  
            active <= 1;  
            timer_reset <= 0;  
        end else if (active) begin  
            if (counter < timeout) begin  
                counter <= counter + 1;  
                timer_reset <= 0;  
            end else begin  
                timer_reset <= 1;  
            end  
        end  
    end  
endmodule

