module deserializer (
    input clk,
    input reset,
    input valid,
    input serial_in,
    output reg [15:0] parallel_out
);
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            parallel_out <= 16'b0;
        end else if (valid) begin
            if (count < 16) begin
                parallel_out <= {serial_in, parallel_out[15:1]};
                count <= count + 1;
            end
        end
    end
endmodule

