module uart_transmitter (
    input clk,
    input rst,
    input enable,
    input [7:0] data_in,
    output reg tx,
    output reg busy
);

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit

    localparam IDLE = 4'd0, START = 4'd1, DATA = 4'd2, STOP = 4'd3;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            tx <= 1; // idle state is high
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (enable) begin
                        shift_reg <= {1'b1, data_in, 1'b0}; // Start with stop bit, then data, then start bit
                        state <= START;
                        busy <= 1;
                        bit_count <= 0;
                    end
                end
                START: begin
                    tx <= 0; // Send start bit
                    state <= DATA;
                end
                DATA: begin
                    if (bit_count < 8) begin
                        tx <= shift_reg[bit_count]; // Send data bits
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP;
                    end
                end
                STOP: begin
                    tx <= 1; // Send stop bit
                    busy <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

