module crc_generator (
    input wire clk,
    input wire rst,
    input wire [15:0] data_in,
    input wire data_valid,
    output reg [15:0] crc_out
);
    reg [15:0] crc_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            crc_reg <= 16'hFFFF; // Initial CRC value
            crc_out <= 16'h0000;
        end else if (data_valid) begin
            crc_reg[15] <= crc_reg[14] ^ data_in[15];
            crc_reg[14] <= crc_reg[13] ^ data_in[14];
            crc_reg[13] <= crc_reg[12] ^ data_in[13];
            crc_reg[12] <= crc_reg[11] ^ data_in[12];
            crc_reg[11] <= crc_reg[10] ^ data_in[11];
            crc_reg[10] <= crc_reg[9] ^ data_in[10];
            crc_reg[9] <= crc_reg[8] ^ data_in[9];
            crc_reg[8] <= crc_reg[7] ^ data_in[8];
            crc_reg[7] <= crc_reg[6] ^ data_in[7];
            crc_reg[6] <= crc_reg[5] ^ data_in[6];
            crc_reg[5] <= crc_reg[4] ^ data_in[5];
            crc_reg[4] <= crc_reg[3] ^ data_in[4];
            crc_reg[3] <= crc_reg[2] ^ data_in[3];
            crc_reg[2] <= crc_reg[1] ^ data_in[2];
            crc_reg[1] <= crc_reg[0] ^ data_in[1];
            crc_reg[0] <= data_in[0];
        end
        crc_out <= crc_reg;
    end
endmodule

module carry_save_adder (
    input [3:0] a,
    input [3:0] b,
    input [3:0] c,
    output [3:0] sum,
    output carry_out
);
    wire [4:0] tmp_sum1, tmp_sum2;

    // First stage of addition: add a and b
    assign tmp_sum1 = a + b;

    // Second stage of addition: add the result with c
    assign tmp_sum2 = tmp_sum1 + c;

    // Final sum and carry out
    assign sum = tmp_sum2[3:0];
    assign carry_out = tmp_sum2[4];

endmodule

