module viterbi_decoder (  
    input clk,  
    input reset,  
    input [1:0] encoded_bits,  
    output reg [1:0] decoded_bits  
);  
    reg [2:0] state;  
    parameter STATE_0 = 3'b000, STATE_1 = 3'b001, STATE_2 = 3'b010, STATE_3 = 3'b011;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= STATE_0;  
            decoded_bits <= 2'b00;  
        end else begin  
            case(state)  
                STATE_0: begin  
                    if (encoded_bits == 2'b00) begin  
                        state <= STATE_0;  
                        decoded_bits <= 2'b00;  
                    end else begin  
                        state <= STATE_1;  
                        decoded_bits <= 2'b01;  
                    end  
                end  
                STATE_1: begin  
                    if (encoded_bits == 2'b01) begin  
                        state <= STATE_2;  
                        decoded_bits <= 2'b10;  
                    end else begin  
                        state <= STATE_3;  
                        decoded_bits <= 2'b11;  
                    end  
                end  
                STATE_2: begin  
                    state <= STATE_0;  
                    decoded_bits <= 2'b00;  
                end  
                STATE_3: begin  
                    state <= STATE_1;  
                    decoded_bits <= 2'b01;  
                end  
                default: begin  
                    state <= STATE_0;  
                    decoded_bits <= 2'b00;  
                end  
            endcase  
        end  
    end  
endmodule

