module pcie_request_gen (
    input wire clk,
    input wire reset,
    input wire request_in,
    output reg ack_out
);
    reg [2:0] state;
    localparam IDLE = 3'b000, WAIT = 3'b001, ACK = 3'b010;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            ack_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (request_in) begin
                        state <= WAIT;
                    end
                end
                WAIT: begin
                    state <= ACK;
                end
                ACK: begin
                    ack_out <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

