module PLL8x (
    input wire clk,
    input wire rst,
    output reg out
);
    reg [2:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 3'b000;
            out <= 0;
        end else begin
            count <= count + 1;
            if (count == 3'b111) begin
                out <= ~out; // Toggle output every 8 counts
            end
        end
    end
endmodule

