module crystal_oscillator (
    input wire clk,          // Clock input
    input wire reset,        // Asynchronous reset
    input wire [3:0] freq_ctrl, // Frequency control input (4-bit)
    output reg osc_out       // Oscillator output
);

reg [3:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        counter <= 0;
        osc_out <= 0;
    end else begin
        counter <= counter + 1;
        if (counter >= (1 << freq_ctrl) - 1) begin
            osc_out <= ~osc_out; // Toggle output
            counter <= 0; // Reset counter
        end
    end
end

endmodule

