module uart_transmitter(  
    input wire clk,  
    input wire reset,  
    input wire start_tx,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg busy  
);  
    parameter IDLE = 2'b00;  
    parameter START = 2'b01;  
    parameter DATA = 2'b10;  
    parameter STOP = 2'b11;  

    reg [1:0] state;  
    reg [3:0] bit_count;  
    reg [9:0] shift_reg; // 1 start + 8 data + 1 stop  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            tx <= 1; // idle state for UART is high  
            busy <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    busy <= 0;  
                    if (start_tx) begin  
                        shift_reg <= {1'b1, data_in, 1'b0}; // start bit, data, stop bit  
                        bit_count <= 0;  
                        state <= START;  
                        busy <= 1;  
                    end  
                end  
                START: begin  
                    tx <= 0; // send start bit  
                    state <= DATA;  
                end  
                DATA: begin  
                    if (bit_count < 8) begin  
                        tx <= shift_reg[bit_count];  
                        bit_count <= bit_count + 1;  
                    end else begin  
                        state <= STOP;  
                    end  
                end  
                STOP: begin  
                    tx <= 1; // send stop bit  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

