module pitch_detector (
    input clk,
    input reset,
    input audio_signal,
    output reg [15:0] detected_frequency
);
    reg [15:0] transition_count;
    reg [15:0] cycle_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            transition_count <= 0;
            cycle_count <= 0;
            detected_frequency <= 0;
        end else begin
            if (audio_signal) begin
                transition_count <= transition_count + 1;
            end
            cycle_count <= cycle_count + 1;

            if (cycle_count >= 1000) begin // 1 second period at 1 kHz
                detected_frequency <= transition_count;
                transition_count <= 0;
                cycle_count <= 0;
            end
        end
    end
endmodule

