module deserializer (
    input clk,
    input reset,
    input serial_in,
    output reg [7:0] parallel_out,
    output reg valid
);
    reg [2:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 3'b000;
            parallel_out <= 8'b00000000;
            valid <= 1'b0;
        end else begin
            if (count < 3'b111) begin
                parallel_out <= {parallel_out[6:0], serial_in};
                count <= count + 1;
                valid <= 1'b0;
            end else begin
                valid <= 1'b1;
            end
        end
    end
endmodule

