module reset_controller(  
    input wire clk,  
    input wire async_reset,  
    output reg reset_out  
);  
    parameter RESET_DURATION = 5;  
    reg [2:0] counter;  
    always @(posedge clk or posedge async_reset) begin  
        if (async_reset) begin  
            reset_out <= 1'b1;  
            counter <= 3'b0;  
        end else if (reset_out) begin  
            if (counter < RESET_DURATION) begin  
                counter <= counter + 1;  
            end else begin  
                reset_out <= 1'b0;  
            end  
        end  
    end  
endmodule

