module uart_transmitter(  
    input wire clk,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg tx,  
    output reg tx_ready  
);  

    parameter BAUD_RATE_DIV = 16; // Example division for baud rate  
    reg [3:0] bit_index;  
    reg [3:0] counter;  
    reg sending;  

    initial begin  
        tx = 1; // Idle state is high  
        tx_ready = 1;  
        sending = 0;  
        bit_index = 0;  
        counter = 0;  
    end  

    always @(posedge clk) begin  
        if (start && tx_ready) begin  
            sending <= 1;  
            tx_ready <= 0;  
            bit_index <= 0;  
            counter <= 0;  
        end  

        if (sending) begin  
            if (counter < BAUD_RATE_DIV - 1) begin  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
                if (bit_index < 10) begin // 1 start bit, 8 data bits, 1 stop bit  
                    case (bit_index)  
                        0: tx <= 0; // Start bit  
                        1: tx <= data_in[0];  
                        2: tx <= data_in[1];  
                        3: tx <= data_in[2];  
                        4: tx <= data_in[3];  
                        5: tx <= data_in[4];  
                        6: tx <= data_in[5];  
                        7: tx <= data_in[6];  
                        8: tx <= data_in[7];  
                        9: tx <= 1; // Stop bit  
                    endcase  
                    bit_index <= bit_index + 1;  
                end else begin  
                    sending <= 0;  
                    tx_ready <= 1;  
                end  
            end  
        end  
    end  
endmodule

