module spi_controller(  
    input clk,  
    input start,  
    input [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg busy  
);  
    reg [3:0] bit_cnt;  
    reg [7:0] shift_reg;  

    always @(posedge clk) begin  
        if (start && !busy) begin  
            busy <= 1;  
            shift_reg <= data_in;  
            bit_cnt <= 8;  
        end else if (busy) begin  
            data_out <= {data_out[6:0], shift_reg[7]};  
            shift_reg <= {shift_reg[6:0], 1'b0};  
            bit_cnt <= bit_cnt - 1;  
            if (bit_cnt == 1) begin  
                busy <= 0;  
            end  
        end  
    end  
endmodule

