module gradient_descent_optimizer(
    input wire clk,
    input wire rst,
    input wire [7:0] initial_guess,
    input wire [7:0] learning_rate,
    input wire [7:0] target,
    output reg [7:0] updated_guess
);

    reg [7:0] diff;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            updated_guess <= initial_guess;
        end else begin
            diff = target - updated_guess;
            if (diff > 0) begin
                updated_guess <= updated_guess + (learning_rate > diff ? diff : learning_rate);
            end else if (diff < 0) begin
                updated_guess <= updated_guess - (learning_rate > -diff ? -diff : learning_rate);
            end
        end
    end
endmodule

