module dma_controller(  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire [7:0] src_addr,  
    input wire [7:0] dest_addr,  
    output reg [7:0] data_out,  
    output reg status // 0: idle, 1: transferring, 2: complete  
);  
    reg [3:0] counter;  
    reg transferring;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            status <= 0;  
            counter <= 0;  
            transferring <= 0;  
            data_out <= 8'b0;  
        end else begin  
            if (start && !transferring) begin  
                transferring <= 1;  
                status <= 1;  
                counter <= 0;  
            end else if (transferring) begin  
                if (counter < 15) begin  
                    data_out <= src_addr + counter; // Simulate data transfer  
                    counter <= counter + 1;  
                end else begin  
                    transferring <= 0;  
                    status <= 2;  
                end  
            end  
        end  
    end  
endmodule

