module pulse_generator #(parameter PULSE_WIDTH = 4) (  
    input wire clk,  
    input wire trigger,  
    output reg pulse  
);  
    reg [3:0] count;  
    reg generating;  

    always @(posedge clk) begin  
        if (trigger) begin  
            generating <= 1'b1;  
            count <= PULSE_WIDTH;  
        end else if (count > 0) begin  
            count <= count - 1;  
        end else begin  
            generating <= 1'b0;  
        end  
    end  

    always @(posedge clk) begin  
        if (generating && count > 0)  
            pulse <= 1'b1;  
        else  
            pulse <= 1'b0;  
    end  
endmodule

