module fir_filter (
    input clk,
    input reset,
    input signed [15:0] x_in,
    output reg signed [15:0] y_out
);
    parameter N = 32; // number of taps
    reg signed [15:0] coeffs [0:N-1]; // coefficient memory
    reg signed [15:0] x_reg [0:N-1]; // delay line
    integer i;

    // Initialize coefficients (example values)
    initial begin
        coeffs[0] = 16'h0001;
        coeffs[1] = 16'h0001;
        coeffs[2] = 16'h0001;
        // ... Initialize remaining coefficients ...
        coeffs[31] = 16'h0001;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y_out <= 16'h0000;
            for (i = 0; i < N; i = i + 1) begin
                x_reg[i] <= 16'h0000;
            end
        end else begin
            // Shift the input samples in the delay line
            for (i = N-1; i > 0; i = i - 1) begin
                x_reg[i] <= x_reg[i-1];
            end
            x_reg[0] <= x_in;

            // Compute the output sample
            y_out <= 16'h0000;
            for (i = 0; i < N; i = i + 1) begin
                y_out <= y_out + (x_reg[i] * coeffs[i]);
            end
        end
    end
endmodule

