);
    reg [3:0] state;              // State machine state
    reg [3:0] bit_count;          // Bit counter
    reg [15:0] clk_div;           // Clock divider counter
    reg [7:0] data_buffer;        // Buffer for the data to send

    localparam IDLE = 4'd0;
    localparam START_BIT = 4'd1;
    localparam DATA_BITS = 4'd2;
    localparam STOP_BIT = 4'd3;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            tx <= 1; // Idle state for TX is high
            clk_div <= 0;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (send) begin
                        data_buffer <= data_in;
                        state <= START_BIT;
                        busy <= 1;
                    end
                end
                START_BIT: begin
                    tx <= 0; // Send start bit
                    state <= DATA_BITS;
                    clk_div <= 0; // Reset clock divider
                end
                DATA_BITS: begin
                    if (clk_div == (baud_rate - 1)) begin
                        clk_div <= 0;
                        tx <= data_buffer[bit_count]; // Send the current data bit
                        bit_count <= bit_count + 1;
                        if (bit_count == 7) begin
                            state <= STOP_BIT; // Move to stop bit after 8 bits
                        end
                    end else begin
                        clk_div <= clk_div + 1;
                    end
                end
                STOP_BIT: begin
                    if (clk_div == (baud_rate - 1)) begin
                        tx <= 1; // Send stop bit
                        state <= IDLE; // Return to idle state
                        busy <= 0;
                        bit_count <= 0;
                    end else begin
                        clk_div <= clk_div + 1;
                    end
                end
            endcase
        end
    end
endmodule

