module rng_lfsr(  
    input wire clk,  
    input wire reset,  
    input wire [4:0] seed,  
    output reg [4:0] random_number  
);  
    reg [4:0] lfsr;  
    wire feedback;  

    assign feedback = lfsr[4] ^ lfsr[2];  // feedback from bit 4 and bit 2  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr <= seed;  
        end else begin  
            lfsr <= {lfsr[3:0], feedback};  // shift left and insert feedback  
        end  
    end  

    always @(posedge clk) begin  
        random_number <= lfsr;  
    end  
endmodule

