module vco (  
    input [3:0] voltage,  
    input clk,  
    output reg square_wave  
);  
    reg [15:0] counter;  
    wire [15:0] frequency;  

    assign frequency = 1000 + (voltage * 100); // Base frequency is 1000, scales up with voltage

    always @(posedge clk) begin  
        if (counter < frequency)  
            counter <= counter + 1;  
        else begin  
            counter <= 0;  
            square_wave <= ~square_wave;  
        end  
    end  
endmodule

