module I2C_Controller (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg sda,
    output reg scl,
    output reg done
);

    reg [3:0] state;
    reg [2:0] bit_count;

    parameter IDLE = 4'b0000;
    parameter START = 4'b0001;
    parameter SEND_DATA = 4'b0010;
    parameter STOP = 4'b0011;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (start) begin
                    state <= START;
                    done <= 0;
                    bit_count <= 0;
                end
            end
            START: begin
                sda <= 0; // Start condition
                scl <= 1; // Clock high
                state <= SEND_DATA;
            end
            SEND_DATA: begin
                if (bit_count < 8) begin
                    sda <= data_in[7 - bit_count]; // Send MSB first
                    scl <= 1; // Clock high
                    bit_count <= bit_count + 1;
                end else begin
                    state <= STOP;
                end
            end
            STOP: begin
                sda <= 0; // Pull SDA low
                scl <= 1; // Clock high
                sda <= 1; // Stop condition
                done <= 1; // Indicate done
                state <= IDLE; // Return to idle
            end
            default: state <= IDLE;
        endcase
    end
endmodule

