module sliding_window_protocol (
    input clk,
    input reset,
    input ack,
    input [3:0] data_in,
    output reg [3:0] data_out,
    output reg [1:0] state // 00: idle, 01: sending, 10: waiting for ack
);
    reg [1:0] next_state;
    reg [1:0] sent_count; // Count of frames sent

    // State encoding
    localparam IDLE = 2'b00, SENDING = 2'b01, WAITING = 2'b10;

    // Sequential logic for state transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            sent_count <= 0;
            data_out <= 0;
        end else begin
            state <= next_state;
            if (next_state == SENDING)
                data_out <= data_in; // Send data
            else if (next_state == WAITING && ack)
                sent_count <= sent_count + 1; // Increment sent count on ack
        end
    end

    // Combinational logic for next state determination
    always @(*) begin
        case (state)
            IDLE: begin
                if (sent_count < 4)
                    next_state = SENDING;
                else
                    next_state = IDLE;
            end
            SENDING: begin
                next_state = WAITING;
            end
            WAITING: begin
                if (ack)
                    next_state = IDLE;
                else
                    next_state = WAITING;
            end
            default: next_state = IDLE;
        endcase
    end
endmodule

module dma_controller (
    input wire clk,
    input wire reset,
    input wire start,
    input wire channel, // 0 for channel 0, 1 for channel 1
    output reg busy,
    output reg done
);
    reg [1:0] state; // 2 bits for state
    localparam IDLE = 2'b00, TRANSFER = 2'b01, DONE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            busy <= 0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        busy <= 1;
                        done <= 0;
                        state <= TRANSFER;
                    end
                end
                TRANSFER: begin
                    // Simulate transfer time for simplicity
                    busy <= 1;
                    state <= DONE;
                end
                DONE: begin
                    busy <= 0;
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

