module dma_controller (
    input clk,
    input reset,
    input start,
    input [7:0] src_addr,
    input [7:0] dest_addr,
    input [7:0] byte_count,
    output reg done,
    output reg [7:0] curr_src_addr,
    output reg [7:0] curr_dest_addr,
    output reg [7:0] transferred_bytes
);
    reg [2:0] state;
    localparam IDLE = 3'b000, 
               TRANSFERRING = 3'b001, 
               DONE = 3'b010;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            done <= 0;
            curr_src_addr <= 0;
            curr_dest_addr <= 0;
            transferred_bytes <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        curr_src_addr <= src_addr;
                        curr_dest_addr <= dest_addr;
                        transferred_bytes <= 0;
                        state <= TRANSFERRING;
                        done <= 0;
                    end
                end
                TRANSFERRING: begin
                    if (transferred_bytes < byte_count) begin
                        // Simulate data transfer
                        curr_src_addr <= curr_src_addr + 1;
                        curr_dest_addr <= curr_dest_addr + 1;
                        transferred_bytes <= transferred_bytes + 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    done <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

