description:
Implement a simplified version of the ChaCha20 quarter round function. The function will take four 32-bit inputs (a, b, c, d) and output four 32-bit results (a_out, b_out, c_out, d_out) after performing the quarter round transformation defined in the ChaCha20 algorithm. The transformation is defined as follows:
1. a += b; d ^= a; d <<< 16;
2. c += d; b ^= c; b <<< 12;
3. a += b; d ^= a; d <<< 8;
4. c += d; b ^= c; b <<< 7;

code:
module chacha_quarter_round (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    input [31:0] c,
    input [31:0] d,
    output reg [31:0] a_out,
    output reg [31:0] b_out,
    output reg [31:0] c_out,
    output reg [31:0] d_out
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_out <= 0;
            b_out <= 0;
            c_out <= 0;
            d_out <= 0;
        end else begin
            // Quarter round transformation
            a_out <= a + b;
            d_out <= (a_out ^ a) << 16;
            c_out <= c + d_out;
            b_out <= (c_out ^ b) << 12;
            a_out <= a_out + b_out;
            d_out <= (a_out ^ d_out) << 8;
            b_out <= (b_out ^ c_out) << 7;
        end
    end
endmodule

module CSPRNG (  
    input clk,  
    input reset,  
    input [127:0] seed,  
    output reg [127:0] random_number  
);  
