module master_slave_d_latch (  
    input wire D,  
    input wire CLK,  
    output reg Q,  
    output reg Qn  
);  
    reg master;  
    reg slave;  

    always @(posedge CLK) begin  
        master <= D;  
    end  

    always @(negedge CLK) begin  
        slave <= master;  
        Q <= slave;  
        Qn <= ~slave;  
    end  
endmodule

