module simple_des (
    input [7:0] data_in,
    input [3:0] key,
    input clk,
    input rst,
    output reg [7:0] data_out
);
    reg [3:0] round_key[1:0];
    reg [7:0] left, right;

    // Key schedule
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            round_key[0] <= key;
            round_key[1] <= {key[2:0], key[3]}; // Simple rotation
        end
    end

    // Round function (simplified)
    function [7:0] round;
        input [7:0] block;
        input [3:0] rkey;
        begin
            round = {block[3:0] ^ rkey, block[7:4]}; // XOR with round key
        end
    endfunction

    // Main encryption process
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_out <= 8'b0;
            left <= data_in[7:4];
            right <= data_in[3:0];
        end else begin
            // First round
            {left, right} <= round({left, right}, round_key[0]);
            // Swap
            {left, right} <= {right, left};
            // Second round
            data_out <= round({left, right}, round_key[1]);
        end
    end
endmodule

