module dma_controller (
    input wire clk,
    input wire reset,
    input wire enable_ch1,
    input wire enable_ch2,
    input wire request_ch1,
    input wire request_ch2,
    output reg transfer_complete_ch1,
    output reg transfer_complete_ch2,
    output reg [7:0] data_out
);
    reg [7:0] memory [0:255]; // Example memory
    reg [7:0] data_in1;
    reg [7:0] data_in2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            transfer_complete_ch1 <= 0;
            transfer_complete_ch2 <= 0;
            data_out <= 8'd0;
        end else begin
            if (enable_ch1 && request_ch1) begin
                data_out <= memory[data_in1]; // Simulate memory read
                transfer_complete_ch1 <= 1;
            end else begin
                transfer_complete_ch1 <= 0;
            end

            if (enable_ch2 && request_ch2) begin
                data_out <= memory[data_in2]; // Simulate memory read
                transfer_complete_ch2 <= 1;
            end else begin
                transfer_complete_ch2 <= 0;
            end
        end
    end
endmodule

