module NeuralLayer(  
    input wire [7:0] x1,  
    input wire [7:0] x2,  
    output wire [7:0] y  
);  
    parameter w1 = 8'd2; // weight for x1  
    parameter w2 = 8'd3; // weight for x2  
    parameter b = 8'd1;   // bias  

    wire [15:0] weighted_sum;  
    assign weighted_sum = (x1 * w1) + (x2 * w2) + b;  
    assign y = (weighted_sum > 8'd0) ? weighted_sum[7:0] : 8'd0; // ReLU activation  
endmodule

module serializer (
    input wire clk,
    input wire reset,
    input wire [7:0] parallel_data,
    output reg serial_out,
    output reg done
);
    reg [2:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 3'b000;
            serial_out <= 1'b0;
            done <= 1'b0;
        end else if (bit_count < 3'd8) begin
            serial_out <= parallel_data[7 - bit_count];
            bit_count <= bit_count + 1;
            done <= 1'b0;
        end else begin
            done <= 1'b1;
        end
    end
endmodule

module dac_8bit (
    input [7:0] digital_in,
    output [7:0] analog_out
);
    assign analog_out = digital_in; // Direct mapping for the DAC
endmodule

module UART_Controller (
    input wire clk,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    reg [3:0] bit_index;
    reg [7:0] shift_reg;
    reg [3:0] baud_counter;

    parameter BAUD_RATE_DIV = 10; // Adjust based on desired baud rate

    always @(posedge clk) begin
        if (start && !busy) begin
            busy <= 1;
            tx <= 0; // Start bit
            shift_reg <= data_in;
            bit_index <= 0;
            baud_counter <= 0;
        end else if (busy) begin
            if (baud_counter < BAUD_RATE_DIV - 1) begin
                baud_counter <= baud_counter + 1;
            end else begin
                baud_counter <= 0;
                if (bit_index < 8) begin
                    tx <= shift_reg[bit_index]; // Send data bits
                    bit_index <= bit_index + 1;
                end else begin
                    tx <= 1; // Stop bit
                    busy <= 0; // Transmission complete
                end
            end
        end
    end
endmodule

