module ripple_carry_adder(
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [4:0] Sum
);
    wire [3:0] carry;

    // Full adder for the least significant bit
    assign Sum[0] = A[0] ^ B[0] ^ Cin;
    assign carry[0] = (A[0] & B[0]) | (Cin & (A[0] ^ B[0]));

    // Full adder for the second bit
    assign Sum[1] = A[1] ^ B[1] ^ carry[0];
    assign carry[1] = (A[1] & B[1]) | (carry[0] & (A[1] ^ B[1]));

    // Full adder for the third bit
    assign Sum[2] = A[2] ^ B[2] ^ carry[1];
    assign carry[2] = (A[2] & B[2]) | (carry[1] & (A[2] ^ B[2]));

    // Full adder for the most significant bit
    assign Sum[3] = A[3] ^ B[3] ^ carry[2];
    assign Sum[4] = (A[3] & B[3]) | (carry[2] & (A[3] ^ B[3]));
endmodule

module PISO_Shift_Register(  
    input wire clk,  
    input wire load,  
    input wire [7:0] data_in,  
    input wire enable,  
    output reg serial_out  
);  
    reg [7:0] shift_reg;  
    integer counter;  

    always @(posedge clk) begin  
        if (load) begin  
            shift_reg <= data_in;  
            counter <= 0;  
        end else if (enable) begin  
            serial_out <= shift_reg[7];  
            shift_reg <= {shift_reg[6:0], 1'b0};  
            counter <= counter + 1;  
        end  
    end  
endmodule

module uart_controller (
    input wire clk,
    input wire reset,
    input wire send_data,
    input wire [7:0] data_in,
    input wire rx,
    output reg tx,
    output reg data_ready,
    output reg [7:0] data_out
);
    reg [3:0] state;
    reg [3:0] bit_count;

    parameter IDLE = 4'b0000,
              START = 4'b0001,
              DATA = 4'b0010,
              STOP = 4'b0011,
              RECEIVE = 4'b0100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1;
            data_ready <= 0;
            bit_count <= 0;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (send_data) begin
                        state <= START;
                        tx <= 0; // Start bit
                        bit_count <= 0;
                    end
                end

                START: begin
                    state <= DATA;
                end

                DATA: begin
                    if (bit_count < 8) begin
                        tx <= data_in[bit_count]; // Send data bit
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP;
                    end
                end

                STOP: begin
                    tx <= 1; // Stop bit
                    data_ready <= 1; // Data sent
                    state <= IDLE;
                end

                RECEIVE: begin
                    if (!rx) begin // Start bit detected
                        state <= DATA;
                        bit_count <= 0;
                    end else if (bit_count < 8) begin
                        data_out[bit_count] <= rx; // Receive data bit
                        bit_count <= bit_count + 1;
                    end else begin
                        data_ready <= 1; // Data received
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

module polynomial_evaluator (
    input [3:0] a, // Coefficient of x^2
    input [3:0] b, // Coefficient of x
    input [3:0] c, // Constant term
    input [3:0] x, // Input variable
    output [7:0] result // Output of polynomial P(x)
);

    wire [7:0] x_squared;
    wire [7:0] ax_squared;
    wire [7:0] bx;

    assign x_squared = x * x; // Calculate x^2
    assign ax_squared = a * x_squared; // Calculate ax^2
    assign bx = b * x; // Calculate bx

    assign result = ax_squared + bx + c; // P(x) = ax^2 + bx + c

endmodule

module SISO_Shift_Register (
    input clk,
    input reset,
    input serial_in,
    output reg serial_out
);
    reg [3:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shift_reg <= 4'b0000;
            serial_out <= 1'b0;
        end else begin
            shift_reg <= {shift_reg[2:0], serial_in};
            serial_out <= shift_reg[3];
        end
    end
endmodule

