module vco (
    input wire clk,          // Base clock
    input wire reset,        // Reset signal
    input wire [2:0] control_voltage, // 3-bit control voltage input
    output reg vco_out       // Output clock signal
);
    reg [23:0] counter;      // Counter for frequency division
    reg [23:0] frequency_divider;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            vco_out <= 0;
            frequency_divider <= 24'd50000000; // Default divider for 1 Hz
        end else begin
            // Set frequency divider based on control voltage
            frequency_divider <= 24'd50000000 / (control_voltage + 1);
            if (counter < frequency_divider) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                vco_out <= ~vco_out; // Toggle output clock
            end
        end
    end
endmodule

